options.Validate();Reject(()=>(options with{Inputs=[new(3,new())]}).Validate(),"Input steps retain the native five-millisecond clock");Reject(()=>(options with{Inputs=[new(500,new())]}).Validate(),"Input sequences reject duration beyond the tested horizon");Reject(()=>(options with{Inputs=[new(100,new(double.NaN,0))]}).Validate(),"Movement inputs reject non-finite axes");Reject(()=>(options with{Inputs=[new(100,new(0,0,true,128,64))]}).Validate(),"Firing aim retains actual native map bounds");Reject(()=>(options with{Seeds=[7,7]}).Validate(),"Scenario seeds must be distinct");Reject(()=>(options with{Seeds=Enumerable.Range(0,9).ToImmutableArray()}).Validate(),"Scenario count is explicitly bounded");
using(var sampled=new EncounterSession(adapter,doc,entity,7,player))
using(var manual=new EncounterSession(adapter,doc,entity,7,player))
{
    var result=NativeCombatSampling.Run(sampled,options,true);foreach(var step in options.Inputs)for(var ms=0;ms<step.DurationMs;ms+=5)manual.Advance(step.Input,5);
    Check(sampled.PlayerX==manual.PlayerX&&sampled.PlayerY==manual.PlayerY&&sampled.PlayerHp==manual.PlayerHp&&sampled.Shots.SequenceEqual(manual.Shots)&&sampled.PlayerShots.SequenceEqual(manual.PlayerShots),"Timed moving/firing samples exactly match manual native five-millisecond execution");
    Check(result.PlayerMoved&&result.PlayerProjectiles>0&&result.Path.Length==5&&result.Path.First().Ms==0&&result.Path.Last().Ms==400,"Samples retain actual movement, XML weapon fire and bounded 100 ms path points");
    Check(result.Path.Any(p=>p.Y>result.StartY)&&result.EndY==sampled.PlayerY&&result.ExposureSamples.Length==1,"Sampled paths retain native direction changes and density shape without predicting positions");
}
var progress=new List<CombatPreviewProgress>();var report=await CombatPreview.RunAsync(adapter,project,options:options,progress:new Sink(progress));
Check(report.Scenarios.Select(s=>s.Seed).SequenceEqual(new[]{7,8})&&report.Scenarios.All(s=>s.Points.Length==1&&s.Reference.PlayerMoved&&s.Reference.PlayerProjectiles>0),"Every seed retains independent native reference and per-start moving/firing runs");
Check(progress.First().Total==4&&progress.Last().Completed==4&&progress.Select(p=>p.Completed).SequenceEqual(new[]{0,1,2,3,4}),"Multi-seed progress covers every reference and damage start once");
Check(report.Options.Inputs.SequenceEqual(options.Inputs)&&report.Options.InputLabel==options.InputLabel&&report.SourceSha256==SourceVerification.EditedSourceHash(project),"Reports retain exact timed input intent and accepted source provenance");
Check(!report.NoDamageObserved(0),"Invulnerability overrides cannot produce a no-damage classification across seeds");
var again=await CombatPreview.RunAsync(adapter,project,options:options);Check(JsonSerializer.Serialize(report.Scenarios)==JsonSerializer.Serialize(again.Scenarios),"Repeated multi-seed native runs retain deterministic actual samples and paths");
var compiledSource=source.Replace("new State(\"combat\",new Shoot(20,count:2,coolDown:100))","StudioCombatFactory()").Replace("private _ StudioMovingCombat", "static State StudioCombatFactory()=>new State(\"combat\",new Shoot(20,count:2,coolDown:100));private _ StudioMovingCombat");var compiledDoc=new BehaviorDocument(compiledSource,adapter,sourceFile:file);var compiledProject=project with{Source=compiledSource,Identities=compiledDoc.Identities};var compiled=await CombatPreview.RunAsync(adapter,compiledProject,options:options);Check(compiled.Runtime=="Compiled source"&&compiled.BuildId?.Length==64&&compiled.Scenarios.Select(s=>s.Seed).SequenceEqual(new[]{7,8}),"Compiled scenario sampling reuses one verified bundle while initializing each actual seed freshly");
foreach(var scenario in compiled.Scenarios){await using var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,compiledProject with{Seed=scenario.Seed});foreach(var step in options.Inputs)await native.AdvanceAsync(step.Input,step.DurationMs);Check(native.PlayerX==scenario.Reference.EndX&&native.PlayerY==scenario.Reference.EndY&&native.PlayerShots.Sum(s=>s.Count)==scenario.Reference.PlayerProjectiles&&native.PlayerHp==scenario.Reference.RemainingHp,"Compiled preview matches independent native movement/firing execution for seed "+scenario.Seed);}
await using(var sampledWorker=await CompiledRuntime.StartAsync(adapter.ServerRoot,compiledProject))
{
    var workerSample=await sampledWorker.SampleCombatAsync(options);
    Check(sampledWorker.Inputs.Count==80&&sampledWorker.Inputs.Take(40).All(i=>i.Input==options.Inputs[0].Input)&&sampledWorker.Inputs.Skip(40).All(i=>i.Input==options.Inputs[1].Input)&&sampledWorker.Inputs.Select(i=>i.Ms).SequenceEqual(Enumerable.Range(0,80).Select(i=>(long)i*5)),"Compiled combat input history retains exact timed movement and firing rather than idle placeholders");
    await using var replayWorker=await CompiledRuntime.StartAsync(adapter.ServerRoot,compiledProject);
    foreach(var recorded in sampledWorker.Inputs)await replayWorker.AdvanceAsync(recorded.Input,recorded.DurationMs);
    Check(replayWorker.PlayerX==sampledWorker.PlayerX&&replayWorker.PlayerY==sampledWorker.PlayerY&&replayWorker.Shots.SequenceEqual(sampledWorker.Shots)&&replayWorker.PlayerShots.SequenceEqual(sampledWorker.PlayerShots),"Captured compiled sampling inputs reproduce actual movement and both native projectile streams");
}
var idleOptions=options with{Inputs=[new(100,new(1,0))],Seeds=[7]};var idleReport=await CombatPreview.RunAsync(adapter,project,options:idleOptions);Check(idleReport.Reference.Path.Last().Ms==400&&idleReport.Reference.Path.Where(p=>p.Ms>=100).Select(p=>p.X).Distinct().Count()==1,"Short input sequences retain native idle behavior for the remaining horizon");
var sample=report.Points[0].Sample! with{PlayerDied=false,ActualMs=400,RemainingHp=100,InitialHp=100,Coverage="Supported"};var safeReport=report with{Player=player with{Invulnerable=false},Scenarios=[new(7,sample,[new(68.5,64.5,sample,null)]),new(8,sample,[new(68.5,64.5,sample with{RemainingHp=99},null)])]};Check(!safeReport.NoDamageObserved(0),"One damaging seed prevents aggregate no-damage highlighting");safeReport=safeReport with{Scenarios=safeReport.Scenarios.SetItem(1,new(8,sample,[new(68.5,64.5,sample,null)]))};Check(safeReport.NoDamageObserved(0),"Aggregate no-damage requires complete supported observations in every tested seed");safeReport=safeReport with{Scenarios=safeReport.Scenarios.SetItem(1,new(8,sample,[new(68.5,64.5,null,"blocked start")]))};Check(!safeReport.NoDamageObserved(0),"Unavailable starts are excluded from aggregate no-damage observations");
var output=Path.GetFullPath(".artifacts/combat-path");Directory.CreateDirectory(output);var path=Path.Combine(output,"scenarios.json");File.WriteAllText(path,JsonSerializer.Serialize(compiled,BehaviorDocument.JsonOptions));var reopened=JsonSerializer.Deserialize<CombatPreviewReport>(File.ReadAllText(path),BehaviorDocument.JsonOptions)!;Check(reopened.Options.Inputs.SequenceEqual(options.Inputs)&&reopened.Scenarios.Select(s=>s.Seed).SequenceEqual(new[]{7,8})&&reopened.Scenarios.All(s=>s.Reference.Path.Length>0),"Scenario JSON round-trip retains input intent, seeds and actual sampled paths");
using(var cancellation=new CancellationTokenSource()){cancellation.Cancel();var rejected=false;try{await CombatPreview.RunAsync(adapter,project,options:options,cancellation:cancellation.Token);}catch(OperationCanceledException){rejected=true;}Check(rejected,"Cancelled multi-scenario requests do not initialize native runs");}
Check(File.ReadAllText(file)==supplied,"Moving/firing previews and scenario serialization preserve supplied game source");Console.WriteLine($"{checks} native combat-path checks passed.");
